        let density_factor = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let base_penalty = 125.0 + (progress * 140.0); 
        let progress_penalty = 145.0 * (1.0 - progress).powf(4.2);
        score += base_penalty + progress_penalty + (density_factor * 120.0);

        if fitting_bins_count == 0 {
            score -= 450.0; // Stronger bypass for mandatory new bin creation
        }
    }

    // 2. Lookahead Refinement:
    // Refined the penalty for unusable gaps (post_residual < next_item_size) to be more reactive to progress.
    if next_item_size > 0 {
        if post_residual == 0 {
            score -= 105.0; // Increased incentive for perfect closure
        } else if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * (32.0 + (progress * 20.0));
        } else {
            let headroom = post_residual - next_item_size;
            // Slightly reduced the headroom reward to prevent over-prioritizing large empty bins.
            score -= 55.0 * (1.0 - (headroom as f64 / bin_capacity as f64)).powf(0.5);
        }
    }

    // 3. Load Balancing:
    // Non-linear variance penalty to force tighter packing across all active bins.
    if !is_new_bin && open_bins_count > 1 {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation.powf(1.2) * 3.5;
    }

    // 4. End-of-stream Consolidation:
    // Sharpened the transition to force consolidation in the final 15%.
    if progress > 0.85 {
        if !is_new_bin {
            score -= 350.0 * (progress - 0.85) / 0.15;
        } else {
            score += 850.0 * (1.0 + progress);
        }
    }

    // 5. Flexibility metric:
    // Adjusted flexibility to favor bins that can accommodate the next item while maintaining high utilization.
    if !is_new_bin {
        let flexibility = (fitting_bins_count as f64).sqrt() * 20.0;
        score -= flexibility * (1.0 - utilization.powi(5));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let utilization = 1.0 - (bin_residual as f64 / bin_capacity as f64);

    // Mutation: Shift to a dynamic quintic utilization penalty to aggressively suppress 
    // medium-empty bins, while lowering base residual cost to prioritize "tight-fit" matches.
    let mut score = (post_residual as f64 * 1.55) + (utilization.powi(5) * 42.0);

    // 1. Adaptive New Bin Penalty:
    // Increased the base penalty to force higher bin saturation before escalating.
    if is_new_bin {
        let density_factor = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let base_penalty = 92.0 + (progress * 135.0); 
        let progress_penalty = 115.0 * (1.0 - progress).powf(4.0);
        score += base_penalty + progress_penalty + (density_factor * 95.0);

        if fitting_bins_count == 0 {
            score -= 380.0; // Stronger bypass for mandatory new bin creation
        }
    }

    // 2. Lookahead Refinement:
    // Targeted minimization of "dead zones" by weighting the gap relative to next_item_size.
    if next_item_size > 0 {
        if post_residual == 0 {
            score -= 75.0; // Stronger incentive for perfect closure
        } else if post_residual < next_item_size {
            // Penalize tiny unusable gaps more heavily to discourage fragmented fills.
            score += (next_item_size - post_residual) as f64 * (22.0 + (progress * 12.0));
        } else {
            // Reward "Goldilocks" bins: high utilization + room for the next item.
            let headroom = post_residual - next_item_size;
            score -= 60.0 * (1.0 - (headroom as f64 / bin_capacity as f64)).powf(0.4);
        }
    }

    // 3. Load Balancing:
    // Penalize variance relative to the mean to force a more uniform, dense filling profile.
    if !is_new_bin && open_bins_count > 1 {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 2.85;
    }

    // 4. End-of-stream Consolidation:
    // Steeper slope for consolidation in the final 15% to eliminate residual fragmentation.
    if progress > 0.85 {
        if !is_new_bin {
            score -= 250.0 * (progress - 0.85) / 0.15;
        } else {
            score += 600.0 * (1.0 + progress);
        }
    }

    // 5. Flexibility metric:
    // Reward bins that remain "flexible" (able to take future items) with a tighter coupling.
    if !is_new_bin {
        let flexibility = (fitting_bins_count as f64).sqrt() * 16.0;
        score -= flexibility * (1.0 - utilization.powi(3));
    }

    score
}
